PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
PREFIX ref: <http://w3.org/ns/void#>
SELECT ?point ?tsid ?class WHERE {
  ?zone a brick:Zone ; rdfs:label "Perimeter_mid_ZN_3" .
  ?point brick:isPartOf* ?zone ;
         ref:hasTimeseriesId ?tsid .
  ?point a ?class .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?point ?pclass WHERE {
  ?point brick:isPartOf* "http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z02" ; a ?pclass .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?p ?pclass ?v ?vclass WHERE {
  ?zone a brick:Zone ; rdfs:label "Perimeter_mid_ZN_3" .
  ?p brick:isPointOf* ?zone .
  ?p a ?pclass .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?p ?pclass WHERE {
  ?zone rdfs:label "Perimeter_mid_ZN_3" .
  ?p brick:isPointOf* ?zone ; a ?pclass .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?point ?pclass ?ref WHERE {
  ?point brick:isPointOf* [ rdfs:label "Perimeter_mid_ZN_3" ] .
  ?point a ?pclass .
  FILTER(?pclass = brick:Electric_Power_Sensor || ?pclass = brick:Occupancy_Sensor)
  OPTIONAL { ?point ?ref ?t . FILTER(strstarts(str(?ref), "http")) }
}

